}

exercises.solution:
std::size_t align_up(std::size_t offset, std::size_t alignment) {
    auto remainder = offset % alignment;
    auto padding = remainder ? alignment - remainder : 0;
    if (offset > std::numeric_limits<std::size_t>::max() - padding)
        throw std::overflow_error("alignment overflow");
    return offset + padding;
}

