exercises.solution:
class Arena {
    alignas(std::max_align_t) std::byte storage_[256];
    std::size_t used_ = 0;
public:
    void* allocate(std::size_t bytes, std::size_t alignment) {
        void* p = storage_ + used_;
        std::size_t space = sizeof(storage_) - used_;
        if (!std::align(alignment,bytes,p,space)) return nullptr;
        used_ = static_cast<std::byte*>(p) - storage_ + bytes;
        return p;
    }
    void reset() { used_ = 0; }
    std::size_t used() const { return used_; }
};
